// Read each paid job from chain through YOUR RPC — the same scan the gateway does (1,000-block chunks from
// ~600 blocks before creation; stop at JobExpired or one quiet chunk after a completion; at most 96 chunks).
// Set RPC to your own Base endpoint: the review is only independent if the read is yours.
const RPC = 'https://mainnet.base.org';
const OWNER = '0xYourGridOwnerWallet';   // the wallet your Grid node joined with (TAIFOON_OWNER)
// Reviews are credited to the wallet bound to the relayer key on "Submit review". Bind once: sign (personal_sign, with
// OWNER) the message a 403 returns — "Taifoon Grid reviewer\nowner: <owner>\nkey: <key prefix>" — and paste it here;
// leave it '' after the first credited review. It binds OWNER to that key only.
const OWNER_SIGNATURE = '';
const PER_RUN = 2;                        // jobs reviewed per run
const TOPIC0 = {
  '0xb0f0239bfdd96453e24733e18bfc24b70d8fadf123dd977473518dd577ee79b9': 'JobCreated',
  '0x869e2577b006bf47ee981cf6fec2e25583548081c14b98deab587f77b5068038': 'BudgetSet',
  '0xe3fbcc1ea1bdc559ec7f0347efde7655e58b5f45a30b0e4470a583c3ef5496b3': 'JobFunded',
  '0x80c17db79857f338a6a6df68a6883ecc0ce78e2202fe61ed979733573f40538e': 'JobSubmitted',
  '0x0fd54bd364fa9e67f17b091aefe930932c09fe7651cf5ad02c71a418f3341444': 'JobCompleted',
  '0x97237956f8810192811e2c3f273fd02c5d6295206fdd9c62e6fe2bfc19ba9232': 'JobExpired',
  '0x21d71db5be59bb9fa133895586b7404307dd33fb93b16db09dc6f1d9d7d231b0': 'PaymentReleased',
  '0x7ca5472b7ea78c2c0141c5a12ee6d170cf4ce8ed06be3d22c8252ddfc7a6a2c4': 'Refunded',
  '0xae7362b1af91f4492868987b9c73990d780060811551b58728fbe96fd1bab275': 'JobRejected',
};
const PRE = ['JobCreated', 'BudgetSet', 'JobFunded', 'JobSubmitted'];
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
// public RPCs rate-limit bursts of getLogs (HTTP 429): retry with a growing pause, like the gateway does
const rpc = async (method, params) => {
  let last = '';
  for (let a = 0; a < 6; a++) {
    try {
      const r = await this.helpers.httpRequest({ method: 'POST', url: RPC, body: { jsonrpc: '2.0', id: 1, method, params }, json: true });
      if (!r.error) return r.result;
      last = JSON.stringify(r.error).slice(0, 160);
    } catch (e) { last = e.message; }
    await sleep(500 * (a + 1));
  }
  throw new Error(`${method}: ${last}`);
};
const done = $getWorkflowStaticData('global');
done.reviewed = done.reviewed || {};
const jobs = ($input.first().json.jobs || []).filter((j) => !done.reviewed[`${j.chainId}:${j.id}`]).slice(0, PER_RUN);
const out = [];
for (const job of jobs) {
  const head = parseInt(await rpc('eth_blockNumber', []), 16);
  let from = job.createdAt ? Math.max(0, head - Math.ceil((Date.now() / 1000 - job.createdAt) / 2) - 600) : Math.max(0, head - 4000);
  const idTopic = '0x' + BigInt(job.id).toString(16).padStart(64, '0');
  const evidence = []; let chunks = 0; let quiet = 0;
  while (from <= head && chunks < 96) {
    const to = Math.min(head, from + 999);
    const logs = await rpc('eth_getLogs', [{ address: job.contract, fromBlock: '0x' + from.toString(16), toBlock: '0x' + to.toString(16), topics: [null, idTopic] }]);
    chunks++;
    for (const l of logs) evidence.push({ event: TOPIC0[l.topics[0].toLowerCase()] || 'unknown', tx: l.transactionHash, log_index: parseInt(l.logIndex, 16), block: parseInt(l.blockNumber, 16), block_hash: l.blockHash.toLowerCase() });
    if (evidence.some((e) => e.event === 'JobExpired')) break;
    if (evidence.some((e) => ['JobCompleted', 'PaymentReleased', 'JobRejected'].includes(e.event)) && logs.length === 0) quiet++;
    if (quiet >= 1) break;
    from = to + 1;
    if (chunks % 4 === 0) await sleep(250);
  }
  evidence.sort((a, b) => a.block - b.block || a.log_index - b.log_index);
  const seen = evidence.map((e) => e.event);
  const verdict = [...seen].sort().join() === [...(job.events || [])].sort().join() ? 'agree' : 'disagree';
  out.push({ json: { owner: OWNER, ...(OWNER_SIGNATURE ? { owner_signature: OWNER_SIGNATURE } : {}), chainId: job.chainId, jobId: String(job.id), verdict, evidence, points: job.points,
    // what the optional Jev grade is shown: the pre-verdict trail only, never the ending
    items: [{ id: String(job.id), chainId: job.chainId, state: JSON.stringify(evidence.filter((e) => PRE.includes(e.event)).map((e) => e.event)) }] } });
}
return out;

// Attach the Jev grade when the optional node ran; when it is disabled its input passes through (no `graded`).
const rows = $('Read from your RPC').all();
return $input.all().map((it, i) => {
  const g = it.json.graded && it.json.graded[0];
  return { json: { ...rows[i].json, jev: g ? { value: g.value, confidence: g.confidence } : null } };
});

// Remember what was reviewed, so the next run moves on (an active workflow keeps this between runs).
const done = $getWorkflowStaticData('global'); done.reviewed = done.reviewed || {};
const rows = $('Attach grade').all();
return $input.all().map((it, i) => {
  const r = rows[i].json;
  // a transient failure (the gateway could not read the chain, an HTTP error) is retried next run; a verdict is final
  if (!it.json.error && 'credited' in it.json) done.reviewed[`${r.chainId}:${r.jobId}`] = it.json.credited ? 'credited' : (it.json.why || 'reviewed');
  return { json: { jobId: r.jobId, verdict: r.verdict, credited: it.json.credited, points: it.json.points, why: it.json.why, jev: r.jev } };
});
